import dayjs from 'dayjs';
import { isConditionComplete, isValidDays } from './conditions';
import {
  FIELDS,
  getOptionLabel,
  LABELS,
  MEMBERS,
  PRIORITIES,
  SLACK_CHANNELS,
  STATUSES,
} from './constants';
import type {
  ActionType,
  Condition,
  ConditionGroup,
  FieldKey,
  FieldType,
  Operator,
  RuleAction,
  RuleTrigger,
  TriggerEvent,
} from './types';

export function joinList(items: string[], conjunction = 'and') {
  if (items.length <= 1) {
    return items.join('');
  }
  return `${items.slice(0, -1).join(', ')} ${conjunction} ${items[items.length - 1]}`;
}

function plural(count: number, word: string) {
  return `${count} ${word}${count === 1 ? '' : 's'}`;
}

export function formatDate(date: string) {
  return dayjs(date).format('MMM D, YYYY');
}

const EVENT_PHRASES: Record<TriggerEvent, string> = {
  issue_created: 'an issue is created',
  issue_updated: 'an issue is updated',
  comment_added: 'a comment is added',
  due_date_approaching: 'a due date is approaching',
  status_changed: 'the status of an issue changes',
};

export function describeTrigger(trigger: RuleTrigger) {
  if (!trigger.event) {
    return null;
  }
  if (trigger.event !== 'status_changed') {
    return EVENT_PHRASES[trigger.event];
  }
  const from = trigger.fromStatus ? ` from ${getOptionLabel(STATUSES, trigger.fromStatus)}` : '';
  const to = trigger.toStatus ? ` to ${getOptionLabel(STATUSES, trigger.toStatus)}` : '';
  return `${EVENT_PHRASES.status_changed}${from}${to}`;
}

type Describer = (condition: Condition, noun: string) => string;

function describeOptions(condition: Condition, noun: string) {
  const { options = [], multiple } = FIELDS[condition.field!];
  const names = condition.options.map((value) => getOptionLabel(options, value));
  const list = joinList(names, 'or');

  if (multiple) {
    return condition.operator === 'is_any_of'
      ? `${noun} include ${list}`
      : `${noun} do not include ${list}`;
  }
  if (condition.operator === 'is_any_of') {
    return `${noun} is ${list}`;
  }
  return names.length === 1 ? `${noun} is not ${list}` : `${noun} is none of ${joinList(names)}`;
}

const DESCRIBERS: { [T in FieldType]: Partial<Record<Operator, Describer>> } = {
  text: {
    contains: (c, noun) => `${noun} contains "${c.text.trim()}"`,
    not_contains: (c, noun) => `${noun} does not contain "${c.text.trim()}"`,
    equals: (c, noun) => `${noun} is "${c.text.trim()}"`,
    is_empty: (_, noun) => `${noun} is empty`,
  },
  number: {
    equals: (c, noun) => `${noun} is ${c.number}`,
    not_equals: (c, noun) => `${noun} is not ${c.number}`,
    greater_than: (c, noun) => `${noun} is greater than ${c.number}`,
    less_than: (c, noun) => `${noun} is less than ${c.number}`,
    between: (c, noun) => `${noun} is between ${c.min} and ${c.max}`,
  },
  date: {
    before: (c, noun) => `${noun} is before ${formatDate(c.date!)}`,
    after: (c, noun) => `${noun} is after ${formatDate(c.date!)}`,
    within_next_days: (c, noun) => `${noun} is within the next ${plural(Number(c.days), 'day')}`,
    is_empty: (_, noun) => `${noun} is empty`,
  },
  option: { is_any_of: describeOptions, is_none_of: describeOptions },
  boolean: {
    is_true: (_, noun) => `the issue is ${noun}`,
    is_false: (_, noun) => `the issue is not ${noun}`,
  },
};

/** Plain-language condition, `null` while the condition is incomplete */
export function describeCondition(condition: Condition) {
  if (!isConditionComplete(condition)) {
    return null;
  }
  const { type, noun } = FIELDS[condition.field as FieldKey];
  return DESCRIBERS[type][condition.operator!]!(condition, noun);
}

function describeGroupParts(group: ConditionGroup): string[] {
  const conditions = group.conditions
    .map(describeCondition)
    .filter((text): text is string => text !== null);
  const groups = group.groups
    .map((nested) => ({ parts: describeGroupParts(nested), combinator: nested.combinator }))
    .filter(({ parts }) => parts.length > 0)
    .map(({ parts, combinator }) => {
      const text = parts.join(` ${combinator} `);
      return parts.length > 1 ? `(${text})` : text;
    });

  return [...conditions, ...groups];
}

export function describeGroup(group: ConditionGroup) {
  return describeGroupParts(group).join(` ${group.combinator} `);
}

const ACTION_DESCRIBERS: Record<ActionType, (action: RuleAction) => string> = {
  assign_member: (action) =>
    action.memberId
      ? `assign to ${getOptionLabel(MEMBERS, action.memberId)}`
      : 'assign to a member',
  set_priority: (action) =>
    action.priority
      ? `set priority to ${getOptionLabel(PRIORITIES, action.priority)}`
      : 'set the priority',
  add_labels: (action) => {
    const labels = action.labels.map((label) => getOptionLabel(LABELS, label));
    if (labels.length === 0) {
      return 'add labels';
    }
    return labels.length === 1 ? `add the label ${labels[0]}` : `add labels ${joinList(labels)}`;
  },
  move_to_status: (action) =>
    action.status ? `move to ${getOptionLabel(STATUSES, action.status)}` : 'move to a status',
  post_comment: () => 'post a comment',
  send_slack_message: (action) =>
    action.slackChannel
      ? `send a Slack message to ${getOptionLabel(SLACK_CHANNELS, action.slackChannel)}`
      : 'send a Slack message',
  set_due_date: (action) =>
    isValidDays(action.dueInDays)
      ? `set the due date to ${plural(Number(action.dueInDays), 'day')} from now`
      : 'set the due date',
};

export function describeAction(action: RuleAction) {
  return action.type ? ACTION_DESCRIBERS[action.type](action) : null;
}

export function describeRule(values: {
  trigger: RuleTrigger;
  root: ConditionGroup;
  actions: RuleAction[];
}) {
  const trigger = describeTrigger(values.trigger);
  if (!trigger) {
    return null;
  }
  const conditions = describeGroup(values.root);
  const actions = joinList(
    values.actions.map(describeAction).filter((text): text is string => text !== null)
  );

  return [`When ${trigger}`, conditions && `if ${conditions}`, actions && `then ${actions}`]
    .filter(Boolean)
    .join(', ');
}

import dayjs from 'dayjs';
import { isConditionComplete } from './conditions';
import { FIELDS } from './constants';
import type { Condition, ConditionGroup, FieldType, Operator, SampleIssue } from './types';

export type ConditionStatus = 'matched' | 'not_matched' | 'incomplete';

export interface ConditionResult {
  id: string;
  condition: Condition;
  status: ConditionStatus;
}

export interface GroupResult {
  id: string;
  combinator: ConditionGroup['combinator'];
  matched: boolean;
  conditions: ConditionResult[];
  groups: GroupResult[];
}

type IssueValue = SampleIssue[keyof SampleIssue];
type Evaluator = (value: IssueValue, condition: Condition, today: dayjs.Dayjs) => boolean;

const text = (value: IssueValue) => String(value ?? '').toLowerCase();
const list = (value: IssueValue) =>
  Array.isArray(value) ? value : value === null ? [] : [String(value)];

const EVALUATORS: { [T in FieldType]: Partial<Record<Operator, Evaluator>> } = {
  text: {
    contains: (value, c) => text(value).includes(c.text.trim().toLowerCase()),
    not_contains: (value, c) => !text(value).includes(c.text.trim().toLowerCase()),
    equals: (value, c) => text(value) === c.text.trim().toLowerCase(),
    is_empty: (value) => text(value).trim() === '',
  },
  number: {
    equals: (value, c) => value === c.number,
    not_equals: (value, c) => value !== c.number,
    greater_than: (value, c) => Number(value) > Number(c.number),
    less_than: (value, c) => Number(value) < Number(c.number),
    between: (value, c) => Number(value) >= Number(c.min) && Number(value) <= Number(c.max),
  },
  date: {
    before: (value, c) => value !== null && dayjs(String(value)).isBefore(c.date, 'day'),
    after: (value, c) => value !== null && dayjs(String(value)).isAfter(c.date, 'day'),
    within_next_days: (value, c, today) => {
      if (value === null) {
        return false;
      }
      const date = dayjs(String(value));
      return !date.isBefore(today, 'day') && !date.isAfter(today.add(Number(c.days), 'day'), 'day');
    },
    is_empty: (value) => value === null,
  },
  option: {
    is_any_of: (value, c) => list(value).some((item) => c.options.includes(item)),
    is_none_of: (value, c) => !list(value).some((item) => c.options.includes(item)),
  },
  boolean: {
    is_true: (value) => value === true,
    is_false: (value) => value === false,
  },
};

function evaluateCondition(
  condition: Condition,
  issue: SampleIssue,
  today: dayjs.Dayjs
): ConditionStatus {
  if (!isConditionComplete(condition)) {
    return 'incomplete';
  }
  const field = condition.field!;
  const evaluator = EVALUATORS[FIELDS[field].type][condition.operator!]!;
  return evaluator(issue[field], condition, today) ? 'matched' : 'not_matched';
}

/** Incomplete conditions and empty groups count as not matched */
export function evaluateGroup(
  group: ConditionGroup,
  issue: SampleIssue,
  today = dayjs()
): GroupResult {
  const conditions = group.conditions.map((condition) => ({
    id: condition.id,
    condition,
    status: evaluateCondition(condition, issue, today),
  }));
  const groups = group.groups.map((nested) => evaluateGroup(nested, issue, today));
  const outcomes = [
    ...conditions.map((result) => result.status === 'matched'),
    ...groups.map((result) => result.matched),
  ];
  const matched =
    outcomes.length > 0 &&
    (group.combinator === 'and' ? outcomes.every(Boolean) : outcomes.some(Boolean));

  return { id: group.id, combinator: group.combinator, matched, conditions, groups };
}

export function renderPlaceholders(template: string, issue: SampleIssue, assignee: string) {
  return template
    .replace(/{{\s*issue\.title\s*}}/g, issue.title)
    .replace(/{{\s*issue\.assignee\s*}}/g, assignee);
}

import { getValueShape } from './conditions';
import type {
  ActionPayload,
  ActionType,
  Condition,
  ConditionGroup,
  ConditionGroupPayload,
  ConditionPayload,
  RuleAction,
  RulePayload,
  RuleValues,
  ValueShape,
} from './types';

const VALUE_PAYLOADS: Record<ValueShape, (condition: Condition) => ConditionPayload['value']> = {
  text: (condition) => condition.text.trim(),
  number: (condition) => Number(condition.number),
  range: (condition) => ({ min: Number(condition.min), max: Number(condition.max) }),
  date: (condition) => condition.date!,
  days: (condition) => Number(condition.days),
  options: (condition) => condition.options,
  none: () => undefined,
};

function toConditionPayload(condition: Condition): ConditionPayload {
  const shape = getValueShape(condition.field, condition.operator);
  return {
    field: condition.field!,
    operator: condition.operator!,
    ...(shape === 'none' ? {} : { value: VALUE_PAYLOADS[shape](condition) }),
  };
}

function toGroupPayload(group: ConditionGroup): ConditionGroupPayload {
  return {
    combinator: group.combinator,
    conditions: group.conditions.map(toConditionPayload),
    groups: group.groups.map(toGroupPayload),
  };
}

const ACTION_PARAMS: Record<ActionType, (action: RuleAction) => Record<string, unknown>> = {
  assign_member: (action) => ({ memberId: action.memberId }),
  set_priority: (action) => ({ priority: action.priority }),
  add_labels: (action) => ({ labels: action.labels }),
  move_to_status: (action) => ({ status: action.status }),
  post_comment: (action) => ({ comment: action.comment.trim() }),
  send_slack_message: (action) => ({
    channel: action.slackChannel,
    message: action.slackMessage.trim(),
  }),
  set_due_date: (action) => ({ daysFromNow: Number(action.dueInDays) }),
};

function toActionPayload(action: RuleAction): ActionPayload {
  const type = action.type!;
  return { type, ...ACTION_PARAMS[type](action) };
}

/** The submitted rule: only the fields of the chosen event, operators and action types */
export function toRulePayload(values: RuleValues): RulePayload {
  const { event, fromStatus, toStatus } = values.trigger;

  return {
    name: values.name.trim(),
    description: values.description.trim(),
    enabled: values.enabled,
    trigger: event === 'status_changed' ? { event, fromStatus, toStatus } : { event: event! },
    conditions: toGroupPayload(values.root),
    actions: values.actions.map(toActionPayload),
  };
}

import type { UseFormReturnType } from '@mantine/form';

export type TriggerEvent =
  | 'issue_created'
  | 'issue_updated'
  | 'comment_added'
  | 'due_date_approaching'
  | 'status_changed';

export type FieldKey =
  | 'title'
  | 'description'
  | 'status'
  | 'priority'
  | 'assignee'
  | 'labels'
  | 'storyPoints'
  | 'dueDate'
  | 'createdAt'
  | 'isBlocked';

export type FieldType = 'text' | 'number' | 'date' | 'option' | 'boolean';

export type Operator =
  | 'contains'
  | 'not_contains'
  | 'equals'
  | 'is_empty'
  | 'not_equals'
  | 'greater_than'
  | 'less_than'
  | 'between'
  | 'before'
  | 'after'
  | 'within_next_days'
  | 'is_any_of'
  | 'is_none_of'
  | 'is_true'
  | 'is_false';

/** Which input the value of a condition needs */
export type ValueShape = 'text' | 'number' | 'range' | 'date' | 'days' | 'options' | 'none';

export type Combinator = 'and' | 'or';

export interface ConditionValueFields {
  text: string;
  number: number | string;
  min: number | string;
  max: number | string;
  date: string | null;
  days: number | string;
  options: string[];
}

export interface Condition extends ConditionValueFields {
  id: string;
  field: FieldKey | null;
  operator: Operator | null;
}

export interface ConditionGroup {
  id: string;
  combinator: Combinator;
  conditions: Condition[];
  groups: ConditionGroup[];
}

export type ActionType =
  | 'assign_member'
  | 'set_priority'
  | 'add_labels'
  | 'move_to_status'
  | 'post_comment'
  | 'send_slack_message'
  | 'set_due_date';

export interface RuleAction {
  id: string;
  type: ActionType | null;
  memberId: string | null;
  priority: string | null;
  labels: string[];
  status: string | null;
  comment: string;
  slackChannel: string | null;
  slackMessage: string;
  dueInDays: number | string;
}

export interface RuleTrigger {
  event: TriggerEvent | null;
  fromStatus: string | null;
  toStatus: string | null;
}

export interface RuleValues {
  name: string;
  description: string;
  enabled: boolean;
  trigger: RuleTrigger;
  root: ConditionGroup;
  actions: RuleAction[];
}

export type RuleFormType = UseFormReturnType<RuleValues>;

export interface Option {
  value: string;
  label: string;
}

export interface SampleIssue {
  title: string;
  description: string;
  status: string;
  priority: string;
  assignee: string | null;
  labels: string[];
  storyPoints: number;
  dueDate: string | null;
  createdAt: string;
  isBlocked: boolean;
}

export interface ConditionPayload {
  field: FieldKey;
  operator: Operator;
  value?: string | number | string[] | { min: number; max: number };
}

export interface ConditionGroupPayload {
  combinator: Combinator;
  conditions: ConditionPayload[];
  groups: ConditionGroupPayload[];
}

export type ActionPayload = { type: ActionType } & Record<string, unknown>;

export interface RulePayload {
  name: string;
  description: string;
  enabled: boolean;
  trigger: { event: TriggerEvent; fromStatus?: string | null; toStatus?: string | null };
  conditions: ConditionGroupPayload;
  actions: ActionPayload[];
}

import type { FormErrors } from '@mantine/form';
import { countConditions, getValueShape, isNumber, isValidDays } from './conditions';
import { COMMENT_PLACEHOLDERS, MAX_DAYS } from './constants';
import type {
  ActionType,
  Condition,
  ConditionGroup,
  RuleAction,
  RuleValues,
  ValueShape,
} from './types';

type Errors = Record<string, string>;

const DAYS_ERROR = `Enter 1 to ${MAX_DAYS} days`;

function required(path: string, valid: boolean, message: string): Errors {
  return valid ? {} : { [path]: message };
}

function rangeRule(condition: Condition, path: string): Errors {
  const { min, max } = condition;
  return {
    ...required(`${path}.min`, isNumber(min), 'Enter a minimum'),
    ...(isNumber(max)
      ? required(`${path}.max`, !isNumber(min) || min < max, 'Must be greater than the minimum')
      : { [`${path}.max`]: 'Enter a maximum' }),
  };
}

const VALUE_RULES: Record<ValueShape, (condition: Condition, path: string) => Errors> = {
  text: (condition, path) =>
    required(`${path}.text`, condition.text.trim() !== '', 'Enter a value'),
  number: (condition, path) =>
    required(`${path}.number`, isNumber(condition.number), 'Enter a number'),
  range: rangeRule,
  date: (condition, path) => required(`${path}.date`, condition.date !== null, 'Pick a date'),
  days: (condition, path) => required(`${path}.days`, isValidDays(condition.days), DAYS_ERROR),
  options: (condition, path) =>
    required(`${path}.options`, condition.options.length > 0, 'Select at least one value'),
  none: () => ({}),
};

function validateCondition(condition: Condition, path: string): Errors {
  if (!condition.field) {
    return { [`${path}.field`]: 'Select a field' };
  }
  if (!condition.operator) {
    return { [`${path}.operator`]: 'Select an operator' };
  }
  return VALUE_RULES[getValueShape(condition.field, condition.operator)](condition, path);
}

// Errors are collected in display order, the first key is the field focused after submit
function validateGroup(group: ConditionGroup, path: string, nested: boolean): Errors {
  const emptyError = nested
    ? 'Add at least one condition to this group'
    : 'Add at least one condition';

  return {
    ...required(`${path}.conditions`, countConditions(group) > 0, emptyError),
    ...Object.assign(
      {},
      ...group.conditions.map((condition, index) =>
        validateCondition(condition, `${path}.conditions.${index}`)
      )
    ),
    ...Object.assign(
      {},
      ...group.groups.map((child, index) => validateGroup(child, `${path}.groups.${index}`, true))
    ),
  };
}

function unknownPlaceholder(text: string) {
  return (text.match(/{{[^}]*}}/g) ?? []).find(
    (placeholder) => !COMMENT_PLACEHOLDERS.includes(placeholder.replace(/\s/g, ''))
  );
}

function commentRule(action: RuleAction, path: string): Errors {
  if (action.comment.trim() === '') {
    return { [`${path}.comment`]: 'Enter a comment' };
  }
  const unknown = unknownPlaceholder(action.comment);
  return required(`${path}.comment`, !unknown, `Unknown placeholder ${unknown}`);
}

const ACTION_RULES: Record<ActionType, (action: RuleAction, path: string) => Errors> = {
  assign_member: (action, path) =>
    required(`${path}.memberId`, action.memberId !== null, 'Select a member'),
  set_priority: (action, path) =>
    required(`${path}.priority`, action.priority !== null, 'Select a priority'),
  add_labels: (action, path) =>
    required(`${path}.labels`, action.labels.length > 0, 'Select at least one label'),
  move_to_status: (action, path) =>
    required(`${path}.status`, action.status !== null, 'Select a status'),
  post_comment: commentRule,
  send_slack_message: (action, path) => ({
    ...required(`${path}.slackChannel`, action.slackChannel !== null, 'Select a channel'),
    ...required(`${path}.slackMessage`, action.slackMessage.trim() !== '', 'Enter a message'),
  }),
  set_due_date: (action, path) =>
    required(`${path}.dueInDays`, isValidDays(action.dueInDays), DAYS_ERROR),
};

function validateAction(action: RuleAction, path: string): Errors {
  return action.type
    ? ACTION_RULES[action.type](action, path)
    : { [`${path}.type`]: 'Select an action type' };
}

export function validateRule(values: RuleValues): FormErrors {
  return {
    ...required('name', values.name.trim() !== '', 'Enter a rule name'),
    ...required('trigger.event', values.trigger.event !== null, 'Select a trigger event'),
    ...validateGroup(values.root, 'root', false),
    ...required('actions', values.actions.length > 0, 'Add at least one action'),
    ...Object.assign(
      {},
      ...values.actions.map((action, index) => validateAction(action, `actions.${index}`))
    ),
  };
}
